(() => {
  'use strict';
  const root = document.getElementById('main');
  const state = { user:null, csrf:'', route:'dashboard', cache:{}, installPrompt:null, toastTimer:null };
  const nav = [
    ['dashboard','Painel','grid'],['processos','Processos','briefcase'],['clientes','Clientes','users'],['tarefas','Tarefas e prazos','check'],['agenda','Agenda','calendar'],['documentos','Documentos','file'],['financeiro','Financeiro','wallet'],['equipe','Equipe','team'],['relatorios','Relatórios','chart'],['configuracoes','Configurações','settings']
  ];
  const roleNames={owner:'Sócia(o) titular',admin:'Administradora(or)',lawyer:'Advogada(o)',staff:'Equipe de apoio',finance:'Financeiro',viewer:'Consulta',platform_admin:'Administração da plataforma'};
  const titleMap=Object.fromEntries(nav.map(([id,label])=>[id,label]));
  const pageRoles={dashboard:['owner','admin','lawyer','staff','finance','viewer'],processos:['owner','admin','lawyer','staff','finance','viewer'],clientes:['owner','admin','lawyer','staff','finance','viewer'],tarefas:['owner','admin','lawyer','staff','viewer'],agenda:['owner','admin','lawyer','staff','viewer'],documentos:['owner','admin','lawyer','staff','viewer'],financeiro:['owner','admin','finance'],equipe:['owner','admin','lawyer'],relatorios:['owner','admin','lawyer','finance','viewer'],configuracoes:['owner','admin']};
  const actionRoles={caseCreate:['owner','admin','lawyer'],caseStatus:['owner','admin','lawyer'],clientCreate:['owner','admin','lawyer','staff'],taskWrite:['owner','admin','lawyer','staff'],eventCreate:['owner','admin','lawyer','staff'],documentCreate:['owner','admin','lawyer','staff'],financeWrite:['owner','admin','finance'],teamRead:['owner','admin','lawyer']};
  const canViewPage=(id)=>(pageRoles[id]||[]).includes(state.user?.role);
  const canDo=(action)=>(actionRoles[action]||[]).includes(state.user?.role);
  const iconPaths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18M10 12v2h4v-2"/>',digital:'<path d="M12 11c0 3.5-1 6.5-2.5 9"/><path d="M8.5 7.5A5 5 0 0 1 17 11c0 2.2-.3 4.3-.9 6.2"/><path d="M5.5 10A7 7 0 0 1 12 4a7 7 0 0 1 6.6 4.6"/><path d="M14.3 14.5c-.3 2-.9 3.9-1.8 5.5"/><path d="M5 14c.4-1 .6-2 .6-3"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM20 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',check:'<path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18M8 14h3M8 17h2"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18M16 14h2"/><path d="M3 5V4a2 2 0 0 1 2-2h12"/>',team:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM19 8v6M22 11h-6"/>',chart:'<path d="M3 3v18h18M8 15l4-4 3 3 6-7"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-1.6 2.77-.08-.02a1.7 1.7 0 0 0-1.78.45l-.05.06h-3.2l-.04-.07a1.7 1.7 0 0 0-1.67-.55l-.08.02-1.6-2.77.05-.06a1.7 1.7 0 0 0 .36-1.78l-.03-.08-2.78-1.6.02-.08a1.7 1.7 0 0 0-.46-1.78l-.05-.05v-3.2l.07-.04a1.7 1.7 0 0 0 .55-1.67l-.02-.08 2.77-1.6.06.05a1.7 1.7 0 0 0 1.78.36l.08-.03 1.6-2.78.08.02a1.7 1.7 0 0 0 1.78-.46l.05-.05h3.2l.04.07a1.7 1.7 0 0 0 1.67.55l.08-.02 1.6 2.77-.05.06a1.7 1.7 0 0 0-.36 1.78l.03.08 2.78 1.6-.02.08a1.7 1.7 0 0 0 .46 1.78l.05.05v3.2l-.07.04a1.7 1.7 0 0 0-.55 1.67z"/>',plus:'<path d="M12 5v14M5 12h14"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',logout:'<path d="M10 17l5-5-5-5M15 12H3M12 3h6a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-6"/>',arrow:'<path d="M5 12h14m-7-7 7 7-7 7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',download:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M7 10l5 5 5-5M12 15V3"/>',close:'<path d="m18 6-12 12M6 6l12 12"/>'};
  const ico=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.grid}</svg>`;
  const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=(v)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(v||0));
  const date=(v,opts={day:'2-digit',month:'short',year:'numeric'})=>{if(!v)return '—';const d=new Date(String(v).replace(' ','T'));return Number.isNaN(d.getTime())?'—':new Intl.DateTimeFormat('pt-BR',opts).format(d)};
  const dateTime=(v)=>v?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(String(v).replace(' ','T'))):'Sem horário';
  const initial=(n)=>String(n||'?').trim().split(/\s+/).slice(0,2).map(p=>p[0]||'').join('').toUpperCase();
  const labelStatus=(s)=>({active:'Em andamento',paused:'Pausado',closed:'Encerrado',pending:'Pendente',in_progress:'Em execução',done:'Concluída',cancelled:'Cancelado',pago:'Pago',pendente:'Pendente',trial:'Avaliação',suspended:'Suspenso',audiencia:'Audiência',reuniao:'Reunião',prazo:'Prazo',receita:'Receita',despesa:'Despesa'}[s]||s||'—');
  const status=(s)=>`<span class="status-pill ${esc(s)}">${esc(labelStatus(s))}</span>`;
  const api=async(path,options={})=>{const method=(options.method||'GET').toUpperCase();const headers={Accept:'application/json',...(options.headers||{})};let body=options.body;if(body&&!(body instanceof FormData)&&typeof body!=='string'){headers['Content-Type']='application/json';body=JSON.stringify(body)}if(method!=='GET'&&state.csrf)headers['X-CSRF-Token']=state.csrf;const res=await fetch(path,{method,headers,body,credentials:'same-origin'});const type=res.headers.get('content-type')||'';const data=type.includes('application/json')?await res.json():{};if(res.status===401){state.user=null;if(path!='/api/auth/login'&&path!='/api/auth/webauthn/login-verify')renderAuth(false);throw new Error(data.error||'Sua sessão expirou. Entre novamente.')}if(!res.ok)throw new Error(data.error||`Falha na operação (${res.status}).`);if(data.csrf)state.csrf=data.csrf;return data};
  const toast=(message,type='')=>{let stack=document.querySelector('.toast-stack');if(!stack){stack=document.createElement('div');stack.className='toast-stack';document.body.appendChild(stack)}const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;stack.appendChild(el);setTimeout(()=>{el.remove();if(!stack.children.length)stack.remove()},3800)};
  const modal=(title,body)=>{document.querySelector('.modal-backdrop')?.remove();const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-action="modal-close" aria-label="Fechar">${ico('close')}</button></header><div class="modal-body">${body}</div></section>`;wrap.addEventListener('click',e=>{if(e.target===wrap)wrap.remove()});root.appendChild(wrap);wrap.querySelector('input,select,textarea,button')?.focus()};
  const field=(label,name,type='text',value='',required=false,placeholder='',options=null)=>{let control='';if(options){control=`<select name="${esc(name)}" ${required?'required':''}>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select>`}else if(type==='textarea'){control=`<textarea name="${esc(name)}" placeholder="${esc(placeholder)}">${esc(value)}</textarea>`}else{control=`<input name="${esc(name)}" type="${esc(type)}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${required?'required':''} ${type==='number'?'step="0.01" min="0"':''}>`}return `<div class="field"><label>${esc(label)}${required?' <span aria-hidden="true">*</span>':''}</label>${control}</div>`};
  const submitForm=(submitLabel='Salvar')=>`<div class="modal-foot"><button type="button" class="button button-secondary" data-action="modal-close">Cancelar</button><button class="button button-primary" type="submit">${esc(submitLabel)}</button></div>`;
  const pageHeader=(eyebrow,title,description,actions='')=>`<header class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1 class="page-title">${esc(title)}</h1><p class="page-description">${esc(description)}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</header>`;
  const empty=(title,copy,action='')=>`<div class="empty-state"><div class="empty-mark">${ico('file')}</div><div class="empty-title">${esc(title)}</div><div class="empty-copy">${esc(copy)}</div>${action}</div>`;
  const panel=(title,subtitle,content,action='')=>`<section class="card"><header class="card-header"><div><h2 class="card-title">${esc(title)}</h2>${subtitle?`<div class="card-subtitle">${esc(subtitle)}</div>`:''}</div>${action}</header><div class="card-body">${content}</div></section>`;
  const btn=(label,action,icon='plus',cls='button-primary')=>`<button type="button" class="button ${cls}" data-action="${esc(action)}">${ico(icon,16)}${esc(label)}</button>`;
  const layout=(active,content)=>{const user=state.user||{};const navItems=nav.filter(([id])=>canViewPage(id)).map(([id,label,ic])=>`<button class="nav-link ${active===id?'active':''}" data-nav="${id}">${ico(ic)}<span>${esc(label)}</span>${id==='tarefas'&&state.cache.overdue?`<span class="pill-number">${state.cache.overdue}</span>`:''}</button>`).join('');const pnav=nav.filter(x=>['dashboard','processos','tarefas','agenda'].includes(x[0])&&canViewPage(x[0])).map(([id,label,ic])=>`<button class="${active===id?'active':''}" data-nav="${id}">${ico(ic,19)}<span>${esc(id==='dashboard'?'Painel':id==='processos'?'Casos':id==='tarefas'?'Prazos':'Agenda')}</span></button>`).join('');const platform=user.role==='platform_admin';const fullNav=platform?`<button class="nav-link ${active==='plataforma'?'active':''}" data-nav="plataforma">${ico('settings')}<span>Escritórios</span></button>`:navItems;root.innerHTML=`<div class="layout"><aside class="sidebar" id="sidebar"><a class="brand" href="#/dashboard"><img src="/assets/lexcloud-icon-192.png" alt=""><span><div class="brand-name">AdvCloud</div><div class="brand-sub">Gestão jurídica</div></span></a><div class="nav-label">Escritório</div><nav class="nav-list" aria-label="Navegação principal">${fullNav}</nav><div class="sidebar-bottom"><div class="tenant-chip"><span class="avatar">${esc(initial(user.tenant_name||'AC'))}</span><div class="tenant-text"><div class="tenant-name">${esc(user.tenant_name||'Plataforma')}</div><div class="tenant-plan">${esc(roleNames[user.role]||'Equipe')}</div></div></div><button class="nav-link pwa-install" data-action="pwa-install">${ico('download')}<span>Instalar app</span></button>${state.user&&!state.user.support?`<button class="nav-link${state.route==='biometria'?' active':''}" data-nav="biometria">${ico('digital')}<span>Biometria</span></button>`:''}<button class="nav-link" data-action="logout">${ico('logout')}<span>Sair da conta</span></button>${APP_VERSION?`<div class="app-versao app-versao-menu" title="Atualizado em ${esc(APP_VERSION_DATE)}">AdvCloud v${esc(APP_VERSION)}</div>`:''}</div></aside><div class="main-wrap"><header class="topbar"><div class="top-actions"><button class="icon-button mobile-menu" data-action="mobile-menu" aria-label="Abrir menu">${ico('menu')}</button><div class="crumb">${esc(user.tenant_name||'AdvCloud')} <span aria-hidden="true">/</span> <strong>${esc(titleMap[active]||(active==='biometria'?'Biometria':'Administração'))}</strong></div></div><div class="top-actions"><div class="search-wrap"><span class="search-icon">${ico('search',16)}</span><input class="search-input" data-global-search placeholder="Buscar neste módulo" aria-label="Buscar"></div><button class="icon-button" data-action="notifications" aria-label="Avisos">${ico('bell')}</button><div class="user-menu"><span class="avatar">${esc(initial(user.name))}</span><div class="user-meta"><div class="user-name">${esc(user.name)}</div><div class="user-role">${esc(roleNames[user.role]||'Equipe')}</div></div></div></div></header>${user.support?`<div class="support-bar" role="status"><span title="O que você fizer aqui fica registrado como &quot;Suporte CHS&quot;">Escritório <strong>${esc(user.tenant_name||'')}</strong> · acesso CHS</span><button type="button" class="button button-secondary button-small" data-action="support-exit">Voltar ao painel</button></div>`:''}<main class="page-content">${content}</main></div><nav class="mobile-nav" aria-label="Navegação móvel">${pnav}<button class="more-button" data-action="mobile-menu">${ico('menu',19)}<span>Mais</span></button></nav></div><div id="modal-host"></div>`};
  const authBrand=`<div class="auth-brand"><img src="/assets/lexcloud-icon-192.png" alt=""><span>AdvCloud</span></div>`;
  function renderPasswordChange(){root.innerHTML=`<section class="auth-page"><aside class="auth-aside">${authBrand}<div class="auth-message"><div class="eyebrow">Proteção da conta</div><h1>Antes de continuar, escolha uma senha pessoal.</h1><p>A senha temporária foi criada pelo administrador do escritório. Troque-a agora e não reutilize uma senha de outros serviços.</p></div><div class="auth-quote">Acesso individual · dados do escritório protegidos</div></aside><div class="auth-main"><div class="auth-form-wrap"><h2>Trocar senha temporária</h2><p>Use ao menos 12 caracteres e mantenha sua senha em local seguro.</p><form class="auth-form" data-form="password-change">${field('Senha temporária atual','current_password','password','',true)}${field('Nova senha pessoal','new_password','password','',true)}${field('Confirme a nova senha','confirm_password','password','',true)}<div class="auth-error"></div><button class="button button-primary" type="submit">Salvar nova senha</button></form></div></div></section>`;}

  const authPage=(eyebrow,h1,texto,titulo,sub,form,rodape='')=>{root.innerHTML=`<section class="auth-page"><aside class="auth-aside">${authBrand}<div class="auth-message"><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(h1)}</h1><p>${esc(texto)}</p></div><div class="auth-quote">Acesso individual · dados do escritório protegidos</div></aside><div class="auth-main"><div class="auth-form-wrap"><h2>${esc(titulo)}</h2><p>${esc(sub)}</p>${form}<div class="auth-switch">${rodape||'<a href="/login">Voltar para o login</a>'}</div></div></div></section>`;};
  function renderForgot(){authPage('Recuperar acesso','Vamos criar uma nova senha.','Enviaremos um link para o e-mail cadastrado. Ele vale por 1 hora e só pode ser usado uma vez.','Esqueci minha senha','Informe o e-mail da sua conta.',`<form class="auth-form" data-form="forgot">${field('E-mail','email','email','',true,'voce@escritorio.com.br')}<div class="auth-error"></div><button class="button button-primary" type="submit">Enviar link ${ico('arrow',15)}</button></form>`);}
  function renderReset(token){authPage('Recuperar acesso','Escolha a sua senha.','Use ao menos 12 caracteres e não reutilize senhas de outros serviços.','Criar nova senha','Depois disso, entre com o seu e-mail e a nova senha.',`<form class="auth-form" data-form="reset"><input type="hidden" name="token" value="${esc(token)}">${field('Nova senha','new_password','password','',true,'Mínimo de 12 caracteres')}${field('Confirme a nova senha','confirm_password','password','',true)}<div class="auth-error"></div><button class="button button-primary" type="submit">Salvar senha ${ico('arrow',15)}</button></form>`);}
  function renderSetup(){authPage('Instalação','Primeiro acesso da plataforma.','Esta tela só existe enquanto não há administrador da plataforma. Depois de criar, ela se desativa sozinha.','Criar administrador da plataforma','Use o código SETUP_TOKEN configurado no servidor.',`<form class="auth-form" data-form="setup">${field('Código de instalação (SETUP_TOKEN)','setup_token','password','',true)}${field('Seu nome','name','text','',true)}${field('E-mail','email','email','',true)}${field('Senha','password','password','',true,'Mínimo de 12 caracteres')}<div class="auth-error"></div><button class="button button-primary" type="submit">Criar administrador ${ico('arrow',15)}</button></form>`);}
  function renderAuth(register=false,error=''){const creating=register;root.innerHTML=`<section class="auth-page"><aside class="auth-aside">${authBrand}<div class="auth-message"><div class="eyebrow">${creating?'Seu escritório, organizado':'Gestão jurídica com clareza'}</div><h1>${creating?'Comece com a rotina em ordem.':'O trabalho jurídico, em um só lugar.'}</h1><p>Processos, prazos, tarefas e relacionamento com clientes conectados à rotina do seu escritório.</p></div><div class="auth-quote">“A melhor decisão é aquela que começa com a informação organizada.”</div></aside><div class="auth-main"><div class="auth-form-wrap"><h2>${creating?'Criar conta do escritório':'Bem-vindo!'}</h2><p>${creating?'Configure seu espaço de trabalho e convide a equipe depois.':'Entre para acompanhar os casos, tarefas e prazos do seu escritório.'}</p><form class="auth-form" data-form="${creating?'register':'login'}">${creating?`${field('Seu nome','name','text','',true,'Nome e sobrenome')}${field('Nome do escritório','office_name','text','',true,'Ex.: Costa & Martins Advocacia')}`:''}${creating?field('E-mail profissional','email','email','',true,'voce@escritorio.com.br'):field('E-mail ou usuário','email','text','',true,'voce@escritorio.com.br ou usuario')}${field('Senha','password','password','',true,creating?'Mínimo de 12 caracteres':'Sua senha')}${creating?'<div class="field-hint">Use uma senha longa e exclusiva. A troca de senha ficará disponível após entrar.</div>':''}<div class="auth-error">${esc(error)}</div><button class="button button-primary" type="submit">${creating?'Criar escritório':'Entrar no AdvCloud'} ${ico('arrow',15)}</button>${!creating&&bioOk()?`<button class="button button-secondary bio-btn" type="button" data-action="bio-login">${ico('digital',17)} Entrar com digital ou Face ID</button>`:''}</form><div class="auth-switch">${creating?'Já tem acesso? <a href="/login">Entrar</a>':`<a href="#/esqueci">Esqueci minha senha</a>${state.signup?' · Primeira vez por aqui? <a href="/cadastro">Criar um escritório</a>':''}${state.setup?' · <a href="#/instalar">Primeiro acesso da plataforma</a>':''}`}</div><div class="auth-privacy">Seus dados jurídicos são privados e pertencem ao seu escritório. Nunca compartilhe credenciais por e-mail.</div>${APP_VERSION?`<p class="app-versao" title="Atualizado em ${esc(APP_VERSION_DATE)}">Versão ${esc(APP_VERSION)}</p>`:''}</div></div></section>`;}
  const getItems=async(path)=>{const r=await api(path);return r.items||[]};
  async function renderDashboard(){const d=await api('/api/dashboard');state.cache.overdue=d.stats.tasks_overdue;const s=d.stats;const financeCard=s.receivable===null?'':`<article class="card stat-card"><div class="stat-top"><div class="stat-label">Recebíveis do mês</div><span class="stat-icon">${ico('wallet')}</span></div><div class="stat-value" style="font-size:23px">${money(s.receivable)}</div><div class="stat-foot">Valores pendentes até o fim do mês</div></article>`;const tasks=d.tasks.length?`<div class="list-stack">${d.tasks.map(t=>`<div class="list-row"><span class="priority-dot ${esc(t.priority)}"></span><div class="list-main"><div class="list-title">${esc(t.title)}</div><div class="list-meta">${esc(t.case_subject||'Sem processo vinculado')} · ${esc(t.assignee_name||'Sem responsável')}</div></div><div class="date-pill">${t.due_at?dateTime(t.due_at):'Sem prazo'}</div>${canDo('taskWrite')?`<button class="row-action" data-task-done="${t.id}" title="Concluir tarefa">Concluir</button>`:''}</div>`).join('')}</div>`:empty('Sem tarefas pendentes','Quando a equipe criar atividades, elas aparecerão aqui.');const events=d.events.length?d.events.map(e=>`<div class="agenda-row"><div class="agenda-time">${dateTime(e.starts_at)}</div><div class="agenda-line"></div><div class="agenda-info"><div class="agenda-type">${esc(labelStatus(e.event_type))}</div><div class="agenda-name">${esc(e.title)}</div><div class="agenda-meta">${esc(e.case_subject||e.location||'Agenda do escritório')}</div></div></div>`).join(''):empty('Agenda livre','Cadastre audiência, reunião ou compromisso.');const cases=d.cases.length?`<div class="list-stack">${d.cases.map(c=>`<div class="list-row"><span class="priority-dot"></span><div class="list-main"><div class="list-title">${esc(c.subject)}</div><div class="list-meta">${esc(c.area)} · ${esc(labelStatus(c.status))}</div></div><div class="date-pill">${c.next_deadline?`Prazo ${date(c.next_deadline)}`:'Sem prazo'}</div></div>`).join('')}</div>`:empty('Sem processos','Cadastre seu primeiro processo para acompanhar prazos.');root.querySelector('.page-content').innerHTML=pageHeader('Visão geral',`Bom dia, ${(state.user.name.split(' ').find(w=>!/^(dr|dra|sr|sra|prof|profa)\.?$/i.test(w))||state.user.name).replace(/[.,]$/,'')}.`,'A rotina do escritório, organizada para hoje.',(canDo('caseCreate')?btn('Novo processo','new-case','plus'):''))+`<div class="grid stats-grid"><article class="card stat-card"><div class="stat-top"><div class="stat-label">Processos ativos</div><span class="stat-icon">${ico('briefcase')}</span></div><div class="stat-value">${s.cases_active}</div><div class="stat-foot">${s.cases_total} no total</div></article><article class="card stat-card"><div class="stat-top"><div class="stat-label">Prazos próximos · 7 dias</div><span class="stat-icon">${ico('calendar')}</span></div><div class="stat-value">${s.tasks_due_soon}</div><div class="stat-foot">Tarefas com vencimento próximo</div></article><article class="card stat-card"><div class="stat-top"><div class="stat-label">Atenção necessária</div><span class="stat-icon">${ico('clock')}</span></div><div class="stat-value">${s.tasks_overdue}</div><div class="stat-foot ${s.tasks_overdue?'urgent':''}">${s.tasks_overdue?'Tarefas vencidas':'Nenhuma tarefa vencida'}</div></article>${financeCard}</div>${s.tasks_overdue?'<div class="alert-banner danger">Há tarefas vencidas. Revise os responsáveis e a situação no módulo Tarefas e prazos.</div>':''}<div class="grid dash-grid">${panel('Minha lista de trabalho','Atividades abertas mais próximas do prazo',tasks,`<button class="button button-quiet button-small" data-nav="tarefas">Ver todas ${ico('arrow',14)}</button>`)}<div class="grid">${panel('Próximos compromissos','Audiências e eventos da agenda',events,`<button class="button button-quiet button-small" data-nav="agenda">Abrir agenda ${ico('arrow',14)}</button>`)}${panel('Prazos de processos','Casos com data mais próxima',cases,`<button class="button button-quiet button-small" data-nav="processos">Ver processos ${ico('arrow',14)}</button>`)}</div></div>`;}
  const searchTools=`<input class="table-search" data-table-search placeholder="Buscar..." aria-label="Buscar na lista">`;
  async function renderClients(){const q=new URLSearchParams({q:document.querySelector('[data-table-search]')?.value||''});const items=await getItems('/api/clients?'+q);const rows=items.map(x=>`<tr><td><div class="primary-cell">${esc(x.name)}</div><div class="secondary-cell">${esc(x.kind==='pessoa_juridica'?'Pessoa jurídica':'Pessoa física')}</div></td><td>${esc(x.email||'—')}</td><td>${esc(x.phone||'—')}</td><td>${esc(x.city||'—')}</td><td>${x.cases_count}</td><td>${status(x.status)}</td></tr>`).join('');root.querySelector('.page-content').innerHTML=pageHeader('Relacionamento','Clientes e partes','Pessoas e organizações atendidas pelo escritório.',(canDo('clientCreate')?btn('Novo cliente','new-client'):''))+`<section class="card table-card"><header class="card-header"><div><h2 class="card-title">Base de clientes</h2><div class="card-subtitle">Dados visíveis somente para este escritório</div></div><div class="table-tools">${searchTools}</div></header>${items.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Cliente</th><th>E-mail</th><th>Telefone</th><th>Cidade</th><th>Processos</th><th>Situação</th></tr></thead><tbody>${rows}</tbody></table></div>`:empty('Sua base começa aqui','Cadastre clientes e partes para vincular aos processos.',(canDo('clientCreate')?btn('Cadastrar cliente','new-client'):''))}</section>`;}
  async function renderCases(){const q=new URLSearchParams({q:document.querySelector('[data-table-search]')?.value||''});const items=await getItems('/api/cases?'+q);const rows=items.map(x=>`<tr><td><button class="row-action" data-case-view="${x.id}">${esc(x.subject)}</button><div class="secondary-cell">${esc(x.case_number||'Número não informado')}</div></td><td>${esc(x.client_name)}</td><td>${esc(x.area)}</td><td>${esc(x.owner_name||'—')}</td><td>${x.next_deadline?date(x.next_deadline):'—'}</td><td>${status(x.status)}</td><td><button class="row-action" data-case-view="${x.id}">Detalhes</button></td></tr>`).join('');root.querySelector('.page-content').innerHTML=pageHeader('Operação jurídica','Processos e casos','Acompanhe a carteira, os responsáveis e as próximas datas.',(canDo('caseCreate')?btn('Novo processo','new-case'):''))+`<section class="card table-card"><header class="card-header"><div><h2 class="card-title">Carteira processual</h2><div class="card-subtitle">Processos cadastrados manualmente; captura de tribunais ainda não conectada</div></div><div class="table-tools">${searchTools}</div></header>${items.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Processo</th><th>Cliente</th><th>Área</th><th>Responsável</th><th>Próximo prazo</th><th>Situação</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`:empty('Nenhum processo cadastrado','Abra o primeiro processo e vincule cliente, responsável e prazo.',(canDo('caseCreate')?btn('Cadastrar processo','new-case'):''))}</section>`;}
  async function renderTasks(){const items=await getItems('/api/tasks');const active=items.filter(t=>t.status!=='done'&&t.status!=='cancelled');const overdue=active.filter(t=>t.due_at&&new Date(String(t.due_at).replace(' ','T'))<new Date());const cards=(arr)=>arr.length?`<div class="list-stack">${arr.map(t=>`<div class="list-row"><span class="priority-dot ${esc(t.priority)}"></span><div class="list-main"><div class="list-title">${esc(t.title)}</div><div class="list-meta">${esc(t.case_subject||t.client_name||'Sem vínculo')} · ${esc(t.assignee_name||'Sem responsável')}</div></div><div class="date-pill">${t.due_at?dateTime(t.due_at):'Sem prazo'}</div>${canDo('taskWrite')?`<select class="button button-secondary button-small" aria-label="Atualizar situação" data-task-status="${t.id}"><option value="pending" ${t.status==='pending'?'selected':''}>Pendente</option><option value="in_progress" ${t.status==='in_progress'?'selected':''}>Em execução</option><option value="done">Concluir</option></select>`:status(t.status)}</div>`).join('')}</div>`:empty('Tudo em dia','Nenhuma tarefa aparece nesta lista.');root.querySelector('.page-content').innerHTML=pageHeader('Rotina e prazos','Tarefas e prazos','Distribua atividades e mantenha os prazos visíveis.',(canDo('taskWrite')?btn('Nova tarefa','new-task'):''))+`${overdue.length?`<div class="alert-banner danger">${overdue.length} tarefa(s) vencida(s). Confira os prazos diretamente no processo antes de tomar providências.</div>`:''}<div class="grid dash-grid"><div class="grid">${panel('Em aberto',`${active.length} tarefas pendentes ou em execução`,cards(active))}${panel('Concluídas',`${items.filter(t=>t.status==='done').length} tarefas finalizadas`,cards(items.filter(t=>t.status==='done').slice(0,12)))}</div>${panel('Como usar','Organização operacional','<div class="settings-note"><strong>Prazo com revisão humana</strong>Registre a data confirmada pelo responsável. Esta versão não consulta diários nem calcula prazo processual automaticamente.</div>')}</div>`;}
  async function renderAgenda(){const items=await getItems('/api/events');const grouped={};items.forEach(e=>{const k=String(e.starts_at).slice(0,10);(grouped[k] ||= []).push(e)});const html=items.length?Object.entries(grouped).map(([day,ev])=>`<div class="card" style="margin-bottom:12px"><header class="card-header"><h2 class="card-title">${date(day+'T12:00:00',{weekday:'long',day:'2-digit',month:'long',year:'numeric'})}</h2><span class="tag">${ev.length} compromisso(s)</span></header><div class="card-body">${ev.map(e=>`<div class="agenda-row"><div class="agenda-time">${new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(new Date(String(e.starts_at).replace(' ','T')))}</div><div class="agenda-line"></div><div class="agenda-info"><div class="agenda-type">${esc(labelStatus(e.event_type))}</div><div class="agenda-name">${esc(e.title)}</div><div class="agenda-meta">${esc(e.case_subject||e.location||'Agenda do escritório')} ${e.location?' · '+esc(e.location):''}</div></div></div>`).join('')}</div></div>`).join(''):empty('Sua agenda está vazia','Inclua audiências, reuniões e prazos confirmados.',(canDo('eventCreate')?btn('Novo compromisso','new-event'):''));root.querySelector('.page-content').innerHTML=pageHeader('Calendário','Agenda e audiências','Compromissos registrados pelo escritório, em ordem cronológica.',(canDo('eventCreate')?btn('Novo compromisso','new-event'):''))+`<div class="alert-banner">Confira data, horário e local diretamente na fonte oficial do compromisso. O AdvCloud não sincroniza tribunais ou calendários externos.</div>${html}`;}
  async function renderDocuments(){const items=await getItems('/api/documents');const html=items.length?`<div class="doc-grid">${items.map(d=>`<article class="file-card"><span class="file-icon">${esc((d.file_name.split('.').pop()||'DOC').slice(0,4).toUpperCase())}</span><div class="file-meta"><div class="file-name">${esc(d.file_name)}</div><div class="file-sub">${esc(d.case_subject||d.client_name||'Sem vínculo')} · ${date(d.uploaded_at)}</div><div class="file-sub">${(Number(d.file_size)/1024).toFixed(0)} KB · ${esc(d.uploader_name||'Equipe')}</div></div><a class="icon-button" href="/api/documents/${d.id}/download" aria-label="Baixar ${esc(d.file_name)}">${ico('download',16)}</a></article>`).join('')}</div>`:empty('Sem documentos ainda','Envie documentos vinculados a clientes ou processos.');root.querySelector('.page-content').innerHTML=pageHeader('Arquivo do escritório','Documentos','Arquivos privados com download autenticado.',(canDo('documentCreate')?btn('Enviar documento','new-document'):''))+`<div class="alert-banner">Arquivos são armazenados no MySQL deste projeto (até 12 MB por arquivo). Não envie documentos reais enquanto a política de acesso, retenção e backup do escritório não tiver sido validada.</div><section class="card"><header class="card-header"><div><h2 class="card-title">Repositório</h2><div class="card-subtitle">Somente usuários autenticados deste tenant</div></div><div class="table-tools">${(canDo('documentCreate')?btn('Enviar arquivo','new-document'):'')}</div></header><div class="card-body">${html}</div></section>`;}
  async function renderFinance(){const data=await api('/api/finance');const items=data.items||[];const s=data.summary||{};const rows=items.map(f=>`<tr><td><div class="primary-cell">${esc(f.description)}</div><div class="secondary-cell">${esc(f.case_subject||f.client_name||f.category||'Lançamento')}</div></td><td>${esc(labelStatus(f.entry_type))}</td><td>${f.due_date?date(f.due_date):'—'}</td><td class="primary-cell">${money(f.amount)}</td><td>${status(f.status)}</td><td>${f.status==='pendente'?`<button class="row-action" data-finance-paid="${f.id}">Marcar pago</button>`:''}</td></tr>`).join('');root.querySelector('.page-content').innerHTML=pageHeader('Gestão financeira','Financeiro','Honorários, recebíveis e despesas vinculados à operação.',(canDo('financeWrite')?btn('Novo lançamento','new-finance'):''))+`<div class="grid stats-grid"><article class="card stat-card"><div class="stat-label">Receitas registradas</div><div class="stat-value" style="font-size:22px">${money(s.income)}</div><div class="stat-foot">Lançamentos do escritório</div></article><article class="card stat-card"><div class="stat-label">Despesas registradas</div><div class="stat-value" style="font-size:22px">${money(s.expense)}</div><div class="stat-foot">Lançamentos do escritório</div></article><article class="card stat-card"><div class="stat-label">Saldo de referência</div><div class="stat-value" style="font-size:22px">${money((s.income||0)-(s.expense||0))}</div><div class="stat-foot">Não é conciliação bancária</div></article><article class="card stat-card"><div class="stat-label">Pendências</div><div class="stat-value" style="font-size:22px">${money(s.pending)}</div><div class="stat-foot">Valores marcados como pendentes</div></article></div><section class="card table-card"><header class="card-header"><div><h2 class="card-title">Lançamentos</h2><div class="card-subtitle">Controle interno — sem emissão de boleto, PIX ou nota fiscal</div></div></header>${items.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Descrição</th><th>Tipo</th><th>Vencimento</th><th>Valor</th><th>Situação</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`:empty('Nenhum lançamento','Inclua honorários, recebíveis e despesas do escritório.',(canDo('financeWrite')?btn('Novo lançamento','new-finance'):''))}</section>`;}
  async function renderTeam(){const items=await getItems('/api/team');const canManage=['owner','admin'].includes(state.user.role);const rows=items.map(u=>`<tr><td><div class="primary-cell">${esc(u.name)}</div><div class="secondary-cell">${esc(u.email)}</div></td><td>${esc(roleNames[u.role]||u.role)}</td><td>${u.last_login_at?date(u.last_login_at):'Ainda não entrou'}</td><td>${u.active?status('active'):status('suspended')}</td><td>${canManage&&u.id!==state.user.id?`<button class="row-action" data-user-active="${u.id}" data-active="${u.active?'0':'1'}">${u.active?'Desativar':'Ativar'}</button>`:(u.id===state.user.id?'Conta atual':'—')}</td></tr>`).join('');root.querySelector('.page-content').innerHTML=pageHeader('Acesso e colaboração','Equipe','Gerencie quem acessa os dados deste escritório.',canManage?btn('Adicionar pessoa','new-user'): '')+`<div class="alert-banner">Uma nova pessoa recebe uma senha temporária exibida uma única vez. Compartilhe por canal seguro. Usuários e sessões não são compartilhados entre escritórios.</div><section class="card table-card"><header class="card-header"><div><h2 class="card-title">Membros do escritório</h2><div class="card-subtitle">Papéis controlam os módulos disponíveis</div></div></header><div class="table-wrap"><table class="data-table"><thead><tr><th>Pessoa</th><th>Papel</th><th>Último acesso</th><th>Conta</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></section>`;}
  async function renderReports(){const r=await api('/api/reports');const bars=(rows,totalKey='total')=>rows.length?`<div class="progress-list">${rows.map(x=>{const n=Number(x[totalKey]||0);const max=Math.max(1,...rows.map(y=>Number(y[totalKey]||0)));return `<div class="progress-item"><span class="progress-label">${esc(labelStatus(x.status||x.entry_type||x.name))}</span><div class="progress-track"><div class="progress-fill" style="width:${Math.max(3,n/max*100)}%"></div></div><span class="progress-value">${esc(x[totalKey]||0)}</span></div>`}).join('')}</div>`:empty('Sem dados','Os indicadores aparecem depois dos primeiros registros.');const team=(r.team||[]).map(x=>`<div class="progress-item"><span class="progress-label">${esc(x.name)}</span><div class="progress-track"><div class="progress-fill" style="width:${Math.max(3,Number(x.tasks_done||0)/Math.max(1,Number(x.tasks_total||0))*100)}%"></div></div><span class="progress-value">${Number(x.tasks_done||0)}/${Number(x.tasks_total||0)}</span></div>`).join('')||empty('Sem tarefas','Distribua atividades para visualizar.');root.querySelector('.page-content').innerHTML=pageHeader('Indicadores','Relatórios','Visão operacional do escritório, sem previsões automáticas.')+`<div class="grid report-grid">${panel('Processos por situação','Carteira atual',bars(r.case_statuses))}${panel('Tarefas por situação','Volume de trabalho',bars(r.task_statuses))}${panel('Financeiro por tipo','Lançamentos dos últimos 12 meses',r.finance.length?`<div class="list-stack">${r.finance.map(x=>`<div class="list-row"><div class="list-main"><div class="list-title">${esc(labelStatus(x.entry_type))} · ${esc(labelStatus(x.status))}</div></div><strong>${money(x.total)}</strong></div>`).join('')}</div>`:empty('Sem dados financeiros','Cadastre lançamentos para acompanhar o resumo.'))}${panel('Atividades por pessoa','Tarefas concluídas / total',team)}</div><p class="field-hint" style="margin-top:15px">Relatórios descritivos; não calculam probabilidade de êxito, contingenciamento ou produtividade jurídica validada.</p>`;}
  async function renderSettings(){const d=await api('/api/settings');const s=d.settings;const canManage=['owner','admin'].includes(state.user.role);root.querySelector('.page-content').innerHTML=pageHeader('Administração','Configurações','Identidade e preferências do tenant. Com uma conta por escritório, os dados permanecem separados.',btn('Instalar app','install-app','download','button-secondary'))+`<div class="grid settings-grid"><section class="card"><header class="card-header"><div><h2 class="card-title">Dados do escritório</h2><div class="card-subtitle">Identidade da área de trabalho</div></div></header><div class="card-body"><form class="form-grid" data-form="settings">${field('Nome do escritório','name','text',s.name,true)}<div class="field"><label>Plano</label><input value="${esc(s.plan)}" disabled></div><div class="field"><label>Situação</label><input value="${esc(labelStatus(s.status))}" disabled></div><div class="field"><label>Fuso horário</label><select name="timezone" ${canManage?'':'disabled'}>${[['America/Sao_Paulo','Brasília · São Paulo'],['America/Manaus','Manaus'],['America/Belem','Belém'],['America/Fortaleza','Fortaleza'],['America/Cuiaba','Cuiabá'],['America/Recife','Recife'],['America/Rio_Branco','Rio Branco'],['America/Noronha','Fernando de Noronha']].map(([v,l])=>`<option value="${v}" ${s.timezone===v?'selected':''}>${l}</option>`).join('')}</select></div>${canManage?`<div class="field full"><button class="button button-primary" type="submit">Salvar alterações</button></div>`:''}</form></div></section><aside class="settings-note"><strong>Dados e privacidade</strong>Dados de clientes, processos e arquivos são privados e armazenados com chave de tenant em cada consulta. Configure a política de retenção e backup do banco antes de uso com documentos reais.<br><br><strong>Plano e cobrança</strong>O status exibido é informativo neste MVP. Não há checkout, cobrança ou troca automática de plano configurada.</aside></div>`;}
  async function renderPlatform(){if(state.user.role!=='platform_admin'){throw new Error('Acesso restrito à administração da plataforma.')}const data=await api('/api/platform/tenants');const rows=data.tenants.map(t=>`<tr><td><div class="primary-cell"><button type="button" class="link-tenant" data-action="tenant-support" data-tenant="${Number(t.id)}" title="Abrir o dashboard deste escritório">${esc(t.name)}</button></div><div class="secondary-cell">${esc(t.slug)}</div></td><td>${esc(t.plan)}</td><td><span class="status-pill ${esc(t.status)}">${esc({active:'Ativo',suspended:'Suspenso',trial:'Em teste'}[t.status]||t.status)}</span></td><td>${Number(t.users_count)}</td><td>${Number(t.cases_count)}</td><td>${date(t.created_at)}</td><td><div class="row-actions" style="display:flex;gap:6px;flex-wrap:wrap"><button class="button button-primary button-small" data-action="tenant-support" data-tenant="${Number(t.id)}" title="Abrir o dashboard deste escritório">Acessar</button><button class="button button-secondary button-small" data-action="tenant-invite" data-tenant="${Number(t.id)}">Reenviar convite</button><button class="button button-secondary button-small" data-action="tenant-status" data-tenant="${Number(t.id)}" data-status="${esc(t.status)}">${t.status==='suspended'?'Reativar':'Suspender'}</button></div></td></tr>`).join('');root.querySelector('.page-content').innerHTML=pageHeader('Plataforma','Escritórios','Cadastre os escritórios e acompanhe o uso. Clique no nome ou em "Acessar" para abrir o dashboard do escritório.',`<button class="button button-primary" data-action="platform-new">${ico('plus',15)} Novo escritório</button>`)+`<section class="card table-card"><header class="card-header"><div><h2 class="card-title">Escritórios cadastrados</h2><div class="card-subtitle">Mostra somente metadados e contagens</div></div></header><div class="table-wrap"><table class="data-table"><thead><tr><th>Escritório</th><th>Plano</th><th>Situação</th><th>Usuários</th><th>Processos</th><th>Criado em</th><th>Ações</th></tr></thead><tbody>${rows}</tbody></table></div></section>`;}
  const loading=()=>root.querySelector('.page-content')&&(root.querySelector('.page-content').innerHTML='<div class="grid stats-grid"><div class="card skeleton"></div><div class="card skeleton"></div><div class="card skeleton"></div><div class="card skeleton"></div></div><div class="card skeleton" style="height:280px"></div>');

  const inviteModal=res=>modal('Convite enviado',`<div class="alert-banner">${esc(res.message||'Convite enviado.')} Se o e-mail não chegar, envie o link abaixo por um canal seguro (vale 48 horas, uso único).</div><div class="field" style="margin-top:12px"><label>Link de acesso</label><input id="temp-password" readonly value="${esc(res.invite_link||'')}"></div><div class="modal-foot"><button type="button" class="button button-secondary" data-action="copy-temp">Copiar link</button><button type="button" class="button button-primary" data-action="modal-close">Fechar</button></div>`);
  // ── Instalar o app (PWA), igual ao Gestão de Notas ──
const pwaStandalone=()=>window.navigator.standalone===true||window.matchMedia('(display-mode: standalone)').matches;
const pwaIOS=()=>/iPad|iPhone|iPod/.test(navigator.userAgent)&&!window.MSStream;
function pwaAtualizar(){const pode=!pwaStandalone()&&(!!state.pwaPrompt||pwaIOS());document.documentElement.classList.toggle('pode-instalar',pode);document.documentElement.classList.toggle('instalar-ios',pode&&!state.pwaPrompt&&pwaIOS());document.documentElement.classList.toggle('instalar-dispensado',sessionStorage.getItem('lex_pwa_dispensado')==='1')}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.pwaPrompt=e;pwaAtualizar()});
window.addEventListener('appinstalled',()=>{state.pwaPrompt=null;pwaAtualizar();toast('AdvCloud instalado. Abra pelo ícone na tela inicial.')});
async function pwaInstalar(){if(state.pwaPrompt){const ev=state.pwaPrompt;ev.prompt();const r=await ev.userChoice;state.pwaPrompt=null;pwaAtualizar();if(r&&r.outcome==='accepted')toast('Instalando o AdvCloud…');return}
if(pwaIOS()){modal('Instalar o AdvCloud no iPhone',`<ol class="pwa-passos"><li>No <strong>Safari</strong>, toque no botão <strong>Compartilhar</strong> (quadrado com a seta para cima).</li><li>Role e toque em <strong>Adicionar à Tela de Início</strong>.</li><li>Toque em <strong>Adicionar</strong>. O AdvCloud aparece como um app.</li></ol><p class="page-description">No iPhone, a instalação só funciona pelo Safari.</p>`);return}
toast('Use o menu do navegador (⋮) e escolha "Instalar app" ou "Adicionar à tela inicial".')}
setTimeout(pwaAtualizar,0);
const [APP_VERSION,APP_VERSION_DATE]=(document.querySelector('meta[name=app-version]')?.content||'|').split('|');
const bioOk=()=>!!(window.PublicKeyCredential&&navigator.credentials);
const b64uBuf=s=>{s=s.replace(/-/g,'+').replace(/_/g,'/');while(s.length%4)s+='=';return Uint8Array.from(atob(s),c=>c.charCodeAt(0)).buffer};
const bufB64u=b=>btoa(String.fromCharCode(...new Uint8Array(b))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
const credJson=c=>{const r=c.response,o={id:c.id,rawId:bufB64u(c.rawId),type:c.type,response:{clientDataJSON:bufB64u(r.clientDataJSON)}};if(r.attestationObject)o.response.attestationObject=bufB64u(r.attestationObject);if(r.authenticatorData){o.response.authenticatorData=bufB64u(r.authenticatorData);o.response.signature=bufB64u(r.signature);if(r.userHandle)o.response.userHandle=bufB64u(r.userHandle)}return o};
const nomeAparelho=()=>{const u=navigator.userAgent;return /iPhone/.test(u)?'iPhone':/iPad/.test(u)?'iPad':/Android/.test(u)?'Celular Android':/Windows/.test(u)?'Computador Windows':/Mac/.test(u)?'Mac':'Aparelho'};
async function bioEntrar(){const o=await api('/api/auth/webauthn/login-options');const c=await navigator.credentials.get({publicKey:{challenge:b64uBuf(o.challenge),rpId:o.rpId,userVerification:'required',timeout:o.timeout||60000}});const r=await api('/api/auth/webauthn/login-verify',{method:'POST',body:{credential:credJson(c)}});state.user=r.user;location.hash=r.user.role==='platform_admin'?'#/plataforma':'#/dashboard';await renderPage();toast('Acesso realizado.')}
async function bioCadastrar(){const o=await api('/api/auth/webauthn/register-options');const pk={...o,challenge:b64uBuf(o.challenge),user:{...o.user,id:b64uBuf(o.user.id)},excludeCredentials:(o.excludeCredentials||[]).map(x=>({...x,id:b64uBuf(x.id)}))};const c=await navigator.credentials.create({publicKey:pk});const r=await api('/api/auth/webauthn/register-verify',{method:'POST',body:{credential:credJson(c),device_name:nomeAparelho()}});toast(r.message||'Biometria cadastrada.');await renderBiometria()}
async function renderBiometria(){const d=await api('/api/auth/webauthn/credentials');const itens=d.items||[];const lista=itens.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Aparelho</th><th>Cadastrado em</th><th>Último uso</th><th></th></tr></thead><tbody>${itens.map(i=>`<tr><td><div class="primary-cell">${esc(i.device_name)}</div></td><td>${date(i.created_at)}</td><td>${i.last_used_at?date(i.last_used_at):'—'}</td><td><button class="button button-secondary button-small" data-action="bio-remove" data-id="${Number(i.id)}">Remover</button></td></tr>`).join('')}</tbody></table></div>`:`<p class="page-description" style="padding:18px">Nenhum aparelho cadastrado ainda.</p>`;
document.querySelector('.page-content').innerHTML=pageHeader('Minha conta','Biometria','Entre com a digital, o rosto (Face ID) ou o Windows Hello, sem digitar a senha. A biometria fica no seu aparelho: o sistema guarda só uma chave pública.',bioOk()?`<button class="button button-primary" data-action="bio-register">${ico('digital',16)} Cadastrar este aparelho</button>`:'')+`${bioOk()?'':'<div class="alert-banner">Este navegador não oferece biometria. Use o Chrome, o Safari ou o Edge atualizados.</div>'}<section class="card"><div class="card-header"><div><h2 class="card-title">Aparelhos cadastrados</h2><p class="card-subtitle">Remova os aparelhos que você não usa mais.</p></div></div>${lista}</section>`}
async function renderPage(){if(!state.user){const r=location.hash.replace(/^#\/?/,'').split('/');if(r[0]==='esqueci'){renderForgot();return}if(r[0]==='redefinir'&&r[1]){renderReset(r[1]);return}if(r[0]==='instalar'&&state.setup){renderSetup();return}renderAuth(location.pathname==='/cadastro'&&state.signup);return}if(Number(state.user.must_change_password)===1){renderPasswordChange();return}const route=location.hash.replace(/^#\/?/,'').split('/')[0]||'dashboard';state.route=route;if(route==='plataforma'&&state.user.role==='platform_admin'){layout('plataforma','');loading();try{await renderPlatform()}catch(e){toast(e.message,'error')}return}if(route==='biometria'){layout('biometria','');loading();try{await renderBiometria()}catch(e){toast(e.message,'error')}return}if(state.user.role==='platform_admin'&&route==='dashboard'){location.hash='#/plataforma';return}if(!titleMap[route]){location.hash='#/dashboard';return}if(!canViewPage(route)){location.hash='#/dashboard';toast('Seu perfil não tem acesso a este módulo.','error');return}layout(route,'');loading();try{switch(route){case'dashboard':await renderDashboard();break;case'processos':await renderCases();break;case'clientes':await renderClients();break;case'tarefas':await renderTasks();break;case'agenda':await renderAgenda();break;case'documentos':await renderDocuments();break;case'financeiro':await renderFinance();break;case'equipe':await renderTeam();break;case'relatorios':await renderReports();break;case'configuracoes':await renderSettings();break;}}catch(e){if(e.message.includes('Autenticação necessária'))return;const content=root.querySelector('.page-content');if(content)content.innerHTML=`<div class="alert-banner danger">${esc(e.message)} <button class="button button-secondary button-small" data-action="retry">Tentar novamente</button></div>`;}}
  const openClient=()=>modal('Novo cliente',`<form class="form-grid" data-form="client">${field('Nome','name','text','',true,'Nome completo ou razão social')}${field('Tipo','kind','select','pessoa_fisica',true,'',[['pessoa_fisica','Pessoa física'],['pessoa_juridica','Pessoa jurídica']])}${field('E-mail','email','email','',false,'contato@exemplo.com.br')}${field('Telefone','phone','tel','',false,'(11) 90000-0000')}${field('Cidade','city','text','',false,'Cidade / UF')}${field('Observações internas','notes','textarea','',false,'Registre somente o necessário')}${submitForm()}</form>`);
  const openCase=async()=>{const [clients,team]=await Promise.all([getItems('/api/clients'),getItems('/api/team')]);modal('Novo processo',`<form class="form-grid" data-form="case"><div class="field"><label>Cliente *</label><select name="client_id" required>${clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select>${!clients.length?'<span class="field-hint">Cadastre um cliente antes de criar o processo.</span>':''}</div>${field('Assunto / nome curto','subject','text','',true,'Ex.: Revisão de contrato')}${field('Número do processo','case_number','text','',false,'CNJ, se aplicável')}${field('Área jurídica','area','select','Cível',true,'',[['Cível','Cível'],['Trabalhista','Trabalhista'],['Empresarial','Empresarial'],['Família','Família'],['Tributário','Tributário'],['Criminal','Criminal'],['Administrativo','Administrativo'],['Consumidor','Consumidor'],['Outra','Outra']])}${field('Tipo de atuação','case_type','text','',false,'Contencioso, consultivo…')}${field('Responsável','owner_id','select',state.user.id,false,'',team.map(u=>[u.id,u.name]))}${field('Tribunal / foro','court','text','',false,'Tribunal e comarca')}${field('Parte contrária','opposing_party','text','',false,'Nome da parte')}${field('Prioridade','priority','select','normal',false,'',[['low','Baixa'],['normal','Normal'],['high','Alta']])}${field('Data de abertura','opened_on','date','',false)}${field('Próximo prazo confirmado','next_deadline','date','',false)}${field('Descrição','description','textarea','',false,'Resumo interno do caso')}<p class="field-hint full">O número e os prazos são inseridos pela equipe. Não há sincronização automática com tribunais nesta versão.</p>${submitForm()}</form>`);};
  const openTask=async()=>{const [cases,clients]=await Promise.all([getItems('/api/cases'),getItems('/api/clients')]);const team=canDo('teamRead')?await getItems('/api/team'):[{id:state.user.id,name:state.user.name}];modal('Nova tarefa ou prazo',`<form class="form-grid" data-form="task">${field('Título','title','text','',true,'Ex.: Revisar documentos')}${field('Responsável','assignee_id','select',state.user.id,true,'',team.map(u=>[u.id,u.name]))}${field('Processo vinculado','case_id','select','',false,'',[['','Sem processo'],...cases.map(c=>[c.id,c.subject])])}${field('Cliente vinculado','client_id','select','',false,'',[['','Sem cliente'],...clients.map(c=>[c.id,c.name])])}${field('Prazo e horário','due_at','datetime-local','',false)}${field('Prioridade','priority','select','normal',true,'',[['low','Baixa'],['normal','Normal'],['high','Alta']])}${field('Instruções','description','textarea','',false,'Observação interna')}<p class="field-hint full">Confirme a data processual e a contagem aplicável com o responsável. O sistema não calcula prazo legal.</p>${submitForm()}</form>`);};
  const openEvent=async()=>{const cases=await getItems('/api/cases');modal('Novo compromisso',`<form class="form-grid" data-form="event">${field('Título','title','text','',true,'Ex.: Audiência de instrução')}${field('Tipo','event_type','select','reuniao',true,'',[['audiencia','Audiência'],['reuniao','Reunião'],['prazo','Prazo'],['outro','Outro']])}${field('Data e hora','starts_at','datetime-local','',true)}${field('Término','ends_at','datetime-local','',false)}${field('Processo','case_id','select','',false,'',[['','Sem processo'],...cases.map(c=>[c.id,c.subject])])}${field('Local / link','location','text','',false,'Endereço ou sala virtual')}${field('Notas','notes','textarea','',false,'Detalhes da agenda')}${submitForm()}</form>`);};
  const openFinance=async()=>{const [cases,clients]=await Promise.all([getItems('/api/cases'),getItems('/api/clients')]);modal('Novo lançamento',`<form class="form-grid" data-form="finance">${field('Descrição','description','text','',true,'Ex.: Honorários contratuais')}${field('Tipo','entry_type','select','receita',true,'',[['receita','Receita / honorário'],['despesa','Despesa']])}${field('Valor (R$)','amount','number','',true,'0,00')}${field('Categoria','category','text','',false,'Honorários, custas…')}${field('Vencimento','due_date','date','',false)}${field('Processo','case_id','select','',false,'',[['','Sem processo'],...cases.map(c=>[c.id,c.subject])])}${field('Cliente','client_id','select','',false,'',[['','Sem cliente'],...clients.map(c=>[c.id,c.name])])}${submitForm()}</form>`);};
  const openUser=()=>modal('Adicionar pessoa à equipe',`<form class="form-grid" data-form="team">${field('Nome','name','text','',true,'Nome e sobrenome')}${field('E-mail de acesso','email','email','',true,'pessoa@escritorio.com.br')}${field('Papel','role','select','staff',true,'',[['admin','Administradora(or)'],['lawyer','Advogada(o)'],['staff','Equipe de apoio'],['finance','Financeiro'],['viewer','Consulta']])}<p class="field-hint full">Será criada uma senha temporária aleatória, exibida uma única vez. Combine a troca assim que o usuário entrar.</p>${submitForm('Criar acesso')}</form>`);
  const openDocument=async()=>{const [cases,clients]=await Promise.all([getItems('/api/cases'),getItems('/api/clients')]);modal('Enviar documento',`<form class="form-grid" data-form="document" enctype="multipart/form-data"><div class="field full"><label>Arquivo *</label><div class="upload-box"><input type="file" name="file" required accept=".pdf,.docx,.png,.jpg,.jpeg,.txt,application/pdf,image/png,image/jpeg"><div class="upload-copy">PDF, DOCX, PNG, JPG ou TXT · até 12 MB</div></div></div>${field('Vincular ao processo','case_id','select','',false,'',[['','Sem processo'],...cases.map(c=>[c.id,c.subject])])}${field('Vincular ao cliente','client_id','select','',false,'',[['','Sem cliente'],...clients.map(c=>[c.id,c.name])])}${submitForm('Enviar com segurança')}</form>`);};
  async function handleForm(form){const data=new FormData(form);const type=form.dataset.form;const body=Object.fromEntries(data.entries());
  const map={client:['/api/clients','POST'],case:['/api/cases','POST'],task:['/api/tasks','POST'],event:['/api/events','POST'],finance:['/api/finance','POST'],team:['/api/team','POST'],settings:['/api/settings','PUT']};try{let res;if(type==='forgot'){res=await api('/api/auth/forgot',{method:'POST',body});form.innerHTML=`<div class="alert-banner">${esc(res.message)}</div>`;return}if(type==='reset'){if(body.new_password!==body.confirm_password)throw new Error('A confirmação da senha não confere.');res=await api('/api/auth/reset',{method:'POST',body:{token:body.token,new_password:body.new_password}});toast(res.message);history.replaceState(null,'','/login');renderAuth(false);return}if(type==='setup'){res=await api('/api/platform/setup',{method:'POST',body});state.setup=false;toast(res.message);history.replaceState(null,'','/login');renderAuth(false);return}if(type==='platform-tenant'){res=await api('/api/platform/tenants',{method:'POST',body});document.querySelector('.modal-backdrop')?.remove();inviteModal(res);await renderPage();return}if(type==='password-change'){if(body.new_password!==body.confirm_password)throw new Error('A confirmação da senha não confere.');res=await api('/api/auth/change-password',{method:'POST',body});state.user=res.user;state.csrf=res.csrf;toast('Senha atualizada.');await renderPage();return}if(type==='login'||type==='register'){res=await api(type==='login'?'/api/auth/login':'/api/auth/register',{method:'POST',body});state.user=res.user;state.csrf=res.csrf;location.hash='#/dashboard';toast(type==='login'?'Acesso realizado.':'Escritório criado. Bem-vinda(o) ao AdvCloud.');renderPage();return}if(type==='document'){const file=data.get('file');if(!file||!file.size)throw new Error('Selecione um arquivo.');res=await api('/api/documents',{method:'POST',body:data});}else if(map[type]){if(type==='client'&&body.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email))throw new Error('Informe um e-mail válido.');res=await api(map[type][0],{method:map[type][1],body});}else{return}form.reset();document.querySelector('.modal-backdrop')?.remove();if(type==='team'&&res.temporary_password){modal('Acesso criado — guarde a senha',`<div class="alert-banner">A senha temporária aparece somente agora. Compartilhe por um canal seguro e confirme a troca no primeiro acesso.</div><div class="field"><label>Usuário</label><input readonly value="${esc(body.email)}"></div><div class="field" style="margin-top:12px"><label>Senha temporária</label><input id="temp-password" readonly value="${esc(res.temporary_password)}"></div><div class="modal-foot"><button type="button" class="button button-secondary" data-action="copy-temp">Copiar</button><button type="button" class="button button-primary" data-action="modal-close">Fechar</button></div>`)}else{toast('Alteração salva com sucesso.');await renderPage()}}catch(e){const err=form.querySelector('.auth-error');if(err){err.textContent=e.message}else toast(e.message,'error')}}
  const onClick=async e=>{const navButton=e.target.closest('[data-nav]');if(navButton){location.hash='#/'+navButton.dataset.nav;document.querySelector('.sidebar')?.classList.remove('open');return}const action=e.target.closest('[data-action]')?.dataset.action;if(action){try{switch(action){case'pwa-install':{await pwaInstalar();break}case'bio-login':{try{await bioEntrar()}catch(err){const box=document.querySelector('.auth-error');const m=err&&err.name==='NotAllowedError'?'Biometria cancelada ou não reconhecida.':(err.message||'Não foi possível entrar com a biometria.');if(box){box.textContent=m}else toast(m,'error')}break}case'bio-register':{try{await bioCadastrar()}catch(err){toast(err&&err.name==='InvalidStateError'?'Este aparelho já está cadastrado.':err&&err.name==='NotAllowedError'?'Cadastro cancelado.':(err.message||'Não foi possível cadastrar.'),'error')}break}case'bio-remove':{const el=e.target.closest('[data-action]');if(!confirm('Remover este aparelho? Ele não vai mais entrar por biometria.'))break;await api('/api/auth/webauthn/credentials/'+el.dataset.id,{method:'DELETE'});toast('Aparelho removido.');await renderBiometria();break}case'platform-new':modal('Novo escritório',`<form class="form-grid" data-form="platform-tenant">${field('Nome do escritório','office_name','text','',true,'Ex.: Costa & Martins Advocacia')}${field('Nome do responsável','owner_name','text','',true)}${field('E-mail do responsável','owner_email','email','',true)}<div class="field"><label>Plano</label><select name="plan"><option value="essencial">Essencial</option><option value="profissional">Profissional</option><option value="escritorio">Escritório</option><option value="trial">Teste</option></select></div><div class="field-hint">O responsável recebe um link por e-mail para criar a própria senha.</div><div class="modal-foot">${submitForm('Criar e enviar convite')}</div></form>`);break;case'tenant-status':{const el=e.target.closest('[data-action]');if(!confirm(el.dataset.status==='suspended'?'Reativar este escritório?':'Suspender este escritório? Ninguém dele conseguirá acessar.'))break;const r=await api('/api/platform/tenants/'+el.dataset.tenant+'/status',{method:'POST',body:{}});toast(r.message);await renderPage();break}case'tenant-invite':{const el=e.target.closest('[data-action]');const r=await api('/api/platform/tenants/'+el.dataset.tenant+'/invite',{method:'POST',body:{}});inviteModal(r);break}case'tenant-support':{const el=e.target.closest('[data-action]');const r=await api('/api/platform/tenants/'+el.dataset.tenant+'/support',{method:'POST',body:{}});state.user=r.user;location.hash='#/dashboard';toast('Você está no escritório como CHS.');await renderPage();break}case'support-exit':{const r=await api('/api/platform/support/exit',{method:'POST',body:{}});state.user=r.user;location.hash='#/plataforma';await renderPage();break}
  case'new-client':openClient();break;case'new-case':await openCase();break;case'new-task':await openTask();break;case'new-event':await openEvent();break;case'new-finance':await openFinance();break;case'new-user':openUser();break;case'new-document':await openDocument();break;case'modal-close':document.querySelector('.modal-backdrop')?.remove();break;case'mobile-menu':document.querySelector('.sidebar')?.classList.toggle('open');break;case'logout':{const r=await api('/api/auth/logout',{method:'POST',body:{}});if(r&&r.user){state.user=r.user;location.hash='#/plataforma';await renderPage();break}}state.user=null;state.csrf='';location.hash='';renderAuth(false);break;case'retry':renderPage();break;case'notifications':toast('Sem novos avisos. Confirme seus prazos com as fontes oficiais.');break;case'install-app':if(state.installPrompt){await state.installPrompt.prompt();await state.installPrompt.userChoice;state.installPrompt=null}else toast('No celular ou computador, use o menu do navegador e escolha “Instalar app” ou “Adicionar à tela inicial”.');break;case'copy-temp':await navigator.clipboard.writeText(document.getElementById('temp-password')?.value||'');toast('Senha copiada para a área de transferência.');break;} }catch(err){toast(err.message,'error')}return}
    const done=e.target.closest('[data-task-done]');if(done){try{await api('/api/tasks/'+done.dataset.taskDone,{method:'PUT',body:{status:'done'}});toast('Tarefa concluída.');renderPage()}catch(err){toast(err.message,'error')}return}
    const paid=e.target.closest('[data-finance-paid]');if(paid){try{await api('/api/finance/'+paid.dataset.financePaid,{method:'PUT',body:{status:'pago'}});toast('Lançamento atualizado.');renderPage()}catch(err){toast(err.message,'error')}return}
    const userButton=e.target.closest('[data-user-active]');if(userButton){try{await api('/api/team/'+userButton.dataset.userActive,{method:'PUT',body:{active:userButton.dataset.active==='1'}});toast('Acesso atualizado.');renderPage()}catch(err){toast(err.message,'error')}return}
    const caseButton=e.target.closest('[data-case-view]');if(caseButton){try{const d=await api('/api/cases/'+caseButton.dataset.caseView);const c=d.item;modal('Detalhes do processo',`<div class="grid" style="gap:14px"><div><div class="eyebrow">${esc(c.area)} · ${esc(c.case_number||'Sem número informado')}</div><h3 style="font:500 23px Georgia,serif;margin:0">${esc(c.subject)}</h3><p class="page-description">${esc(c.client_name)} · ${esc(c.owner_name||'Sem responsável')}</p></div><div class="grid" style="grid-template-columns:1fr 1fr"><div class="settings-note"><strong>Situação</strong>${status(c.status)}</div><div class="settings-note"><strong>Próximo prazo</strong>${c.next_deadline?date(c.next_deadline):'Não informado'}</div></div><div class="settings-note"><strong>Descrição</strong>${esc(c.description||'Sem observações.')}</div><div><h4 class="card-title">Histórico recente</h4>${(c.activities||[]).map(a=>`<div class="activity-line"><div class="activity-title">${esc(a.title)}</div><div class="activity-copy">${esc(a.user_name||'Sistema')} · ${dateTime(a.created_at)}${a.body?' · '+esc(a.body):''}</div></div>`).join('')||'<div class="field-hint">Sem atividades registradas.</div>'}</div>${canDo('caseStatus')?`<div class="field"><label>Atualizar situação</label><select data-case-status="${c.id}"><option value="active" ${c.status==='active'?'selected':''}>Em andamento</option><option value="paused" ${c.status==='paused'?'selected':''}>Pausado</option><option value="closed" ${c.status==='closed'?'selected':''}>Encerrado</option></select></div>`:''}</div>`)}catch(err){toast(err.message,'error')}return}
  };
  const onChange=async e=>{const task=e.target.closest('[data-task-status]');if(task){try{await api('/api/tasks/'+task.dataset.taskStatus,{method:'PUT',body:{status:task.value}});toast('Situação da tarefa atualizada.');renderPage()}catch(err){toast(err.message,'error')}}const cs=e.target.closest('[data-case-status]');if(cs){try{await api('/api/cases/'+cs.dataset.caseStatus,{method:'PUT',body:{status:cs.value}});toast('Situação do processo atualizada.');document.querySelector('.modal-backdrop')?.remove();renderPage()}catch(err){toast(err.message,'error')}}};
  const onSubmit=async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();await handleForm(form)};
  const onInput=e=>{if(!e.target.matches('[data-table-search]'))return;clearTimeout(state.searchTimer);state.searchTimer=setTimeout(()=>renderPage(),250)};
  async function init(){root.addEventListener('click',onClick);root.addEventListener('change',onChange);root.addEventListener('submit',onSubmit);root.addEventListener('input',onInput);window.addEventListener('hashchange',renderPage);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.installPrompt=e});window.addEventListener('online',()=>toast('Conexão restaurada. Atualize a tela para sincronizar.'));try{const s=await api('/api/auth/session');state.user=s.user;state.csrf=s.csrf||'';state.signup=!!s.signup;state.setup=!!s.setup}catch(e){state.user=null}if('serviceWorker' in navigator){navigator.serviceWorker.register('/sw.js').catch(()=>{})}if(!location.hash&&state.user)location.hash='#/dashboard';renderPage()}
  init();
})();
